Lemma to_andR3 : forall A1 A2 A3 : Prop, A1 /\ A2 /\ A3 -> andR3 A1 A2 A3.
Proof. intros A1 A2 A3 (h1 & h2 & h3). exact (mkAndR3 h1 h2 h3). Qed.
